  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 The Present Progressive$j$, $j${"readings": [{"title": "Philippians 3 (King James Version)", "url": "/portal/bible/Philippians/3"}], "body": "Philippians 3:14 says, I press toward the mark for the prize of the high calling of God in Christ Jesus. Pressing is an action in progress, and Spanish uses the present progressive for what is happening right now.\n\nForm it with the present tense of estar plus the present participle. For ar verbs add ando to the stem: hablar becomes hablando. For er and ir verbs add iendo: comer becomes comiendo, escribir becomes escribiendo. Estoy hablando, estás comiendo, está escribiendo, estamos orando, están cantando.\n\nWhen the stem ends in a vowel, iendo becomes yendo: leer becomes leyendo, oír becomes oyendo, creer becomes creyendo. Stem changing ir verbs change the vowel: dormir becomes durmiendo, pedir becomes pidiendo, decir becomes diciendo, servir becomes sirviendo, venir becomes viniendo.\n\nPronouns may go before estar or attach to the participle with an accent mark: Me estoy vistiendo or Estoy vistiéndome. Lo estoy leyendo or Estoy leyéndolo.\n\nWorked example: Ahora mismo estoy estudiando español. Mi madre está sirviendo la cena y mis hermanos están durmiendo. Common mistake: using the progressive for the future or for plans, as in English. Spanish uses the present or ir a for that: Mañana voy a estudiar.\n\nYour task: (1) Write the present participle of ten verbs. (2) Describe in six sentences what five people near you are doing right now.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Philippians 3:14 says, I press toward the mark for the prize of the high calling of God in Christ Jesus. Pressing is an action in progress.\n\nNow watch this. Present progressive is estar plus the participle. Ar verbs take ando. Er and ir verbs take iendo. Estoy hablando. Estás comiendo. Está escribiendo.\n\nBetween vowels, use yendo: leyendo, oyendo, creyendo. Stem changers: durmiendo, pidiendo, diciendo, sirviendo, viniendo.\n\nPronouns go before estar or attach to the participle with an accent. Lo estoy leyendo. Estoy leyéndolo.\n\nDo not use the progressive for the future. Say Mañana voy a estudiar.\n\nYour task is to write ten participles and describe what five people are doing. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 The Present Progressive$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The Future Tense$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established. Making plans and committing them to God is a part of life. In Spanish 1 you used ir a plus an infinitive for plans. The simple future tense adds a more formal way to speak about what will happen.\n\nThe future is easy to form: take the whole infinitive and add the endings é, ás, á, emos, án. These endings are the same for ar, er and ir verbs. Hablar becomes hablaré, hablarás, hablará, hablaremos, hablarán. Comer becomes comeré. Vivir becomes viviré. Notice the accents on all forms but nosotros.\n\nTwelve common verbs have irregular stems but use the same endings. Tener is tendr, so tendré. Venir is vendr, poner is pondr, salir is saldr, poder is podr, querer is querr, saber is sabr, hacer is har, decir is dir, haber is habr. Hacer becomes haré, harás, hará, haremos, harán.\n\nWorked example: El próximo año terminaré la escuela. Mis padres me ayudarán. Tendré un trabajo y haré mi servicio en la iglesia. Common mistake: dropping the infinitive. Say hablaré, not habaré. Add the ending to the whole infinitive.\n\nYour task: (1) Conjugate vivir and tener in the future. (2) Write six sentences about what you will do after graduation, using at least two irregular stems.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established. Let us talk about the future.\n\nNow watch this. The future tense uses the whole infinitive plus é, ás, á, emos, án. Hablaré, hablarás, hablará, hablaremos, hablarán. The endings are the same for all three kinds of verbs.\n\nIrregular stems: tendr, vendr, pondr, saldr, podr, querr, sabr, har, dir, habr. Tendré, haré, diré.\n\nDo not drop the infinitive. Hablaré, not habaré.\n\nMañana voy a estudiar and Mañana estudiaré both talk about the future. The first is more common in speech.\n\nYour task is to conjugate vivir and tener and write six sentences about what you will do after graduation. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The Future Tense$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Careers, Technology and the Interview$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. God values every honest job. Learning career and technology vocabulary in Spanish prepares you to work with Spanish speaking coworkers and customers.\n\nCareers include el médico, la enfermera, el maestro, la maestra, el ingeniero, el abogado, el pastor, el mecánico, el electricista, el programador, la cocinera, el contador and el empresario. Note that many nouns for people keep the same form for male or female, such as el estudiante and la estudiante, and the article shows gender.\n\nTechnology words are la computadora, el teléfono, el correo electrónico, el sitio web, la aplicación, la contraseña, el archivo and la pantalla. Never share your contraseña.\n\nFor an interview, useful phrases are Me llamo and Tengo experiencia en. Me gustaría trabajar con ustedes means I would like to work with you. Trabajo bien en equipo means I work well on a team. Estoy aprendiendo español means I am learning Spanish. Use usted in an interview and end with Gracias por su tiempo.\n\nWorked example: Buenos días. Me llamo Daniel. Me gustaría ser programador. Estudio computación y trabajo bien en equipo. Common mistake: using a tú form with an interviewer. Use usted and a polite tone.\n\nYour task: (1) Write a six sentence introduction for a job interview in Spanish. (2) List ten careers and one thing each person does.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Colossians 3:23 says, Whatsoever ye do, do it heartily, as to the Lord. God values every honest job.\n\nNow watch this. Careers: el médico, la enfermera, el maestro, el ingeniero, el abogado, el pastor, el mecánico, el programador, la cocinera.\n\nTechnology: la computadora, el teléfono, el correo electrónico, el sitio web, la aplicación, la contraseña. Never share your contraseña.\n\nInterview phrases: Me llamo. Tengo experiencia en. Me gustaría trabajar con ustedes. Trabajo bien en equipo. Use usted and finish with Gracias por su tiempo.\n\nYour task is to write a six sentence interview introduction and list ten careers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Careers, Technology and the Interview$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Holidays, Traditions and Cultural Respect$j$, $j${"readings": [{"title": "Luke 2 (King James Version)", "url": "/portal/bible/Luke/2"}], "body": "Luke 2:10 says, And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. In the Spanish speaking world, the story of Christmas is celebrated in many beautiful ways, and learning about traditions helps us love our neighbors.\n\nNavidad is Christmas. Nochebuena, Christmas Eve, is often the main family celebration, with a late dinner and church. In many countries, children receive gifts on el Día de los Reyes Magos, January 6, remembering the wise men. Semana Santa, Holy Week, includes services and processions leading to Pascua, Easter. A quinceañera celebrates a girl's fifteenth birthday, often beginning with a church service of thanks. Families gather around foods such as tamales, pan dulce, arroz con pollo and buñuelos.\n\nEach country has its own customs. A Cuban family in Florida may serve lechón on Nochebuena. A Mexican family may share tamales. A Puerto Rican family may sing parrandas. Never assume that all Spanish speakers are the same.\n\nSome traditions mix older cultural and religious customs. A Christian student can study them to understand and respect neighbors, while keeping his own convictions rooted in the Bible. Ask kindly: ¿Cómo celebran ustedes la Navidad?\n\nWorked example: En mi familia, celebramos la Nochebuena con una cena y vamos a la iglesia. Common mistake: using one tradition to describe an entire people. Name the country or community.\n\nYour task: (1) Write six sentences about how your family celebrates one holiday. (2) Write three respectful questions you could ask a Spanish speaking neighbor about their traditions.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Luke 2:10 says, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people. Let us learn how Spanish speaking families celebrate.\n\nNow watch this. Navidad is Christmas. Nochebuena is Christmas Eve, often the main family celebration. El Día de los Reyes Magos is January 6. Semana Santa is Holy Week, and Pascua is Easter. A quinceañera celebrates a girl's fifteenth birthday.\n\nFoods: tamales, pan dulce, arroz con pollo, buñuelos.\n\nEach country has its own customs. Name the country or community, and do not assume that all Spanish speakers are the same.\n\nWe study traditions to understand and respect neighbors, while keeping our convictions rooted in the Bible. Ask kindly. ¿Cómo celebran ustedes la Navidad?\n\nYour task is to write six sentences about your family holiday and three respectful questions. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Holidays, Traditions and Cultural Respect$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Present Progressive, Future Plans, Careers and Traditions$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nPart 1: Explain how to form the present participle and the present progressive, give ten participles including three irregular ones, and write five sentences.\nPart 2: Explain how to form the future tense, conjugate one regular and one irregular verb, and write six sentences about your future.\nPart 3: Write a Spanish introduction of at least eight sentences for a job interview, using career and technology words and polite forms.\nPart 4: Write at least 120 words in English about one Spanish speaking holiday or tradition, with at least eight Spanish words, and describe how to ask about it respectfully.\nPart 5: Explain how Proverbs 16:3 and Colossians 3:23 guide your plans for work and service.\nPart 6: Explain why it is wrong to describe all Spanish speakers as the same, and give an example.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Present Progressive, Future Plans, Careers and Traditions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Plans and Callings$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a job or ministry you hope to have, (2) shares at least three Spanish sentences about your future using the future tense, (3) explains how Spanish could help you serve in that work, and (4) connects your answer to Proverbs 16:3 or Colossians 3:23. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can learning about another culture's holidays help the church welcome its neighbors?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Plans and Callings$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: The Present Progressive$j$, $j${"questions": [{"q": "The participle of hablar is:", "options": ["Hablaendo", "Hablando", "Hablar", "Hablado"]}, {"q": "The participle of leer is:", "options": ["Leiendo", "Leyendo", "Leando", "Leendo"]}, {"q": "Estoy orando means:", "options": ["I am praying", "I will pray", "I prayed", "I pray every day"]}, {"q": "The participle of dormir is:", "options": ["Dormiendo", "Duermendo", "Durmiendo", "Dormendo"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Present Progressive$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,2}'::int[], array[$j$Ar verbs take ando.$j$,$j$Between vowels, iendo becomes yendo.$j$,$j$Estar plus a participle shows an action in progress.$j$,$j$Dormir changes o to u in the participle.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: The Present Progressive$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: The Future Tense$j$, $j${"questions": [{"q": "The yo future of hablar is:", "options": ["Hablaré", "Hablé", "Hablo", "Hablaría"]}, {"q": "The yo future of tener is:", "options": ["Tendré", "Tuvé", "Tengaré", "Teneré"]}, {"q": "Ellos harán means:", "options": ["They were doing", "They do", "They did", "They will do"]}, {"q": "Future endings are the same for:", "options": ["Only ir verbs", "Ar, er and ir verbs", "Only ar verbs", "Only irregular verbs"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Future Tense$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,3,1}'::int[], array[$j$Add é to the whole infinitive.$j$,$j$Tener has the irregular stem tendr.$j$,$j$Harán is the future of hacer.$j$,$j$The future uses the same endings for all verbs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The Future Tense$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Careers, Technology and the Interview$j$, $j${"questions": [{"q": "Me gustaría trabajar con ustedes means:", "options": ["I worked with you", "I will work alone", "I would like to work with you", "I work with you"]}, {"q": "La contraseña is the:", "options": ["Screen", "File", "Phone", "Password"]}, {"q": "In an interview, address the interviewer with:", "options": ["Usted", "Tú", "Ellos", "Vos only"]}, {"q": "El abogado is a:", "options": ["Lawyer", "Doctor", "Mechanic", "Teacher"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Careers, Technology and the Interview$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,0}'::int[], array[$j$Me gustaría expresses a polite wish.$j$,$j$Contraseña means password.$j$,$j$Usted is polite and formal.$j$,$j$Abogado means lawyer.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Careers, Technology and the Interview$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Holidays, Traditions and Cultural Respect$j$, $j${"questions": [{"q": "Nochebuena is:", "options": ["Easter", "Christmas Eve", "New Year's Day", "A birthday"]}, {"q": "La Semana Santa is:", "options": ["A school week", "A Saturday", "A holy day only", "Holy Week"]}, {"q": "A quinceañera celebrates a girl's:", "options": ["Fifth birthday", "Graduation", "Fifteenth birthday", "Wedding"]}, {"q": "The best way to learn about a neighbor's customs is to:", "options": ["Assume everyone is the same", "Criticize them", "Ask respectfully", "Ignore them"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Holidays, Traditions and Cultural Respect$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2}'::int[], array[$j$Nochebuena means good night, Christmas Eve.$j$,$j$Semana Santa leads up to Easter.$j$,$j$Quince means fifteen.$j$,$j$Respectful questions build understanding.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Holidays, Traditions and Cultural Respect$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Present Progressive, Future Plans, Careers and Traditions$j$, $j${"questions": [{"q": "Estamos cantando means:", "options": ["We sang", "We will sing", "We are singing", "We sing"]}, {"q": "The participle of pedir is:", "options": ["Pedando", "Pidendo", "Pidiendo", "Pediendo"]}, {"q": "The nosotros future of hablar is:", "options": ["Hablamos", "Hablaríamos", "Hablábamos", "Hablaremos"]}, {"q": "The yo future of poder is:", "options": ["Poderé", "Podré", "Puedaré", "Pudé"]}, {"q": "El ingeniero is a:", "options": ["Engineer", "Lawyer", "Teacher", "Cook"]}, {"q": "In an interview, a polite phrase is:", "options": ["Hola, amigo", "Adiós ya", "Qué onda", "Gracias por su tiempo"]}, {"q": "El Día de los Reyes Magos is on:", "options": ["July 4", "December 25", "March 1", "January 6"]}, {"q": "Never share your:", "options": ["Aplicación", "Computadora", "Pantalla", "Contraseña"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Present Progressive, Future Plans, Careers and Traditions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,1,0,3,3,3}'::int[], array[$j$Estar plus a participle shows an action in progress.$j$,$j$Pedir changes e to i.$j$,$j$Emos is the future nosotros ending.$j$,$j$Poder has the stem podr.$j$,$j$Ingeniero means engineer.$j$,$j$It means thank you for your time.$j$,$j$It remembers the wise men.$j$,$j$A contraseña is a password.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Present Progressive, Future Plans, Careers and Traditions$j$ on conflict (item_id) do nothing;
